{
  "items": [
    {
      "name": "MvPowerSeries.le_weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {n : ℕ∞},\n  (∀ (d : σ →₀ ℕ), ↑((Finsupp.weight w) d) < n → (MvPowerSeries.coeff d) f = 0) → n ≤ MvPowerSeries.weightedOrder w f"
    },
    {
      "name": "MvPowerSeries.weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_2} → [Semiring R] → (σ → ℕ) → MvPowerSeries σ R → ℕ∞"
    },
    {
      "name": "MvPowerSeries.nat_le_weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {n : ℕ},\n  (∀ (d : σ →₀ ℕ), (Finsupp.weight w) d < n → (MvPowerSeries.coeff d) f = 0) → ↑n ≤ MvPowerSeries.weightedOrder w f"
    },
    {
      "name": "MvPowerSeries.le_order",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] {f : MvPowerSeries σ R} {n : ℕ∞},\n  (∀ (d : σ →₀ ℕ), ↑(Finsupp.degree d) < n → (MvPowerSeries.coeff d) f = 0) → n ≤ f.order"
    },
    {
      "name": "MvPowerSeries.nat_le_order",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] {f : MvPowerSeries σ R} {n : ℕ},\n  (∀ (d : σ →₀ ℕ), Finsupp.degree d < n → (MvPowerSeries.coeff d) f = 0) → ↑n ≤ f.order"
    },
    {
      "name": "natCast_le_analyticOrderAt_iff_iteratedDeriv_eq_zero",
      "module_name": "Mathlib.Analysis.Analytic.Order",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} {E : Type u_2} [inst : NontriviallyNormedField 𝕜] [inst_1 : NormedAddCommGroup E]\n  [inst_2 : NormedSpace 𝕜 E] {f : 𝕜 → E} {n : ℕ} {z₀ : 𝕜} [CharZero 𝕜] [CompleteSpace E],\n  AnalyticAt 𝕜 f z₀ → (↑n ≤ analyticOrderAt f z₀ ↔ ∀ i < n, iteratedDeriv i f z₀ = 0)"
    }
  ]
}
